package formatstudio.runtime;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.nio.ByteBuffer;
import java.nio.charset.CharacterCodingException;
import java.nio.charset.CodingErrorAction;
import java.nio.charset.StandardCharsets;
import java.util.UUID;

/**
 * Reads wire primitives from an {@link InputStream} for code generated by Format Studio (generator "java-stream"):
 * fixed-width integers in both byte orders, LEB128 varints (plain and zigzag), UUIDs as two 64-bit halves, UTF-8
 * strings and raw byte arrays.
 *
 * <p>Unsigned values are widened: u8 and u16 to {@code int}, u32 and varuint32 to {@code long}. 64-bit unsigned values
 * keep their bits in a {@code long}.
 *
 * <p>When the length of the data is known (byte arrays, slices, or the length passed to the constructor), counts are
 * checked against the remaining bytes before anything is allocated; otherwise against {@link #maxCount()}.
 */
public final class FormatReader {
    /**
     * Reads one value. Generated code passes such functions to the code of native types with type arguments
     * ({@code {{T:read}}}).
     */
    @FunctionalInterface
    public interface ValueReader<T> {
        T read(FormatReader reader) throws IOException;
    }

    private final InputStream input;
    private final long length;
    private final byte[] scratch = new byte[8];
    private long position;
    private int peeked = -1;
    private int maxCount = 1 << 24;
    private ByteArrayOutputStream recording;

    /** Reads from a stream of unknown length; reading stops at the end of the stream. */
    public FormatReader(InputStream input) {
        this(input, -1);
    }

    /** Reads at most {@code length} bytes from a stream (-1: unknown). */
    public FormatReader(InputStream input, long length) {
        this.input = input;
        this.length = length;
    }

    public FormatReader(byte[] data) {
        this(new ByteArrayInputStream(data), data.length);
    }

    /** The number of bytes read so far. */
    public long position() {
        return position;
    }

    /**
     * The stream the reader reads from, e.g. for code that decodes the next bytes through other means and then skips
     * them here. With an unknown length, {@link #atEnd} may have read a byte ahead.
     */
    public InputStream input() {
        return input;
    }

    /** The number of bytes left, or -1 when the length is unknown. */
    public long remaining() {
        return length < 0 ? -1 : length - position;
    }

    /** The largest count accepted when the length of the data is unknown. */
    public int maxCount() {
        return maxCount;
    }

    public void setMaxCount(int maxCount) {
        this.maxCount = maxCount;
    }

    /** Whether all bytes have been read (for a stream of unknown length: whether it has ended). */
    public boolean atEnd() throws IOException {
        if (length >= 0) return position >= length;
        if (peeked >= 0) return false;
        peeked = input.read();
        return peeked < 0;
    }

    private FormatDataException missing(int count) {
        return new FormatDataException("Needs " + count + " bytes at offset " + position
            + (length >= 0 ? ", " + remaining() + " remaining" : ", the stream ended"));
    }

    private int next() throws IOException {
        if (length >= 0 && position >= length) throw missing(1);
        int b;
        if (peeked >= 0) {
            b = peeked;
            peeked = -1;
        } else {
            b = input.read();
            if (b < 0) throw missing(1);
        }

        position++;
        if (recording != null) recording.write(b);
        return b;
    }

    private void fill(byte[] target, int count) throws IOException {
        if (length >= 0 && count > length - position) throw missing(count);
        int offset = 0;
        if (count > 0 && peeked >= 0) {
            target[0] = (byte) peeked;
            peeked = -1;
            offset = 1;
        }

        while (offset < count) {
            int read = input.read(target, offset, count - offset);
            if (read < 0) {
                position += offset;
                throw missing(count - offset);
            }
            offset += read;
        }

        position += count;
        if (recording != null) recording.write(target, 0, count);
    }

    private byte[] take(int count) throws IOException {
        if (count < 0) throw new FormatDataException("Negative length " + count + " at offset " + position);
        if (length >= 0 && count > length - position) throw missing(count);
        byte[] bytes = new byte[count];
        fill(bytes, count);
        return bytes;
    }

    private byte[] fixed(int count) throws IOException {
        fill(scratch, count);
        return scratch;
    }

    /** Reads {@code length} bytes as a separate reader (a length-delimited section). */
    public FormatReader slice(int length) throws IOException {
        return new FormatReader(take(length));
    }

    /** Validates a collection count read from the wire before anything is allocated. */
    public int checkCount(long count, int minElementSize, int max) throws FormatDataException {
        if (count < 0) throw new FormatDataException("Negative count " + count + " at offset " + position);
        if (count > max) throw new FormatDataException("Count " + count + " exceeds the maximum of " + max + " at offset " + position);
        if (length >= 0) {
            if (minElementSize > 0 && count > remaining() / minElementSize)
                throw new FormatDataException("Count " + count + " needs at least " + count * minElementSize + " bytes at offset " + position
                    + ", " + remaining() + " remaining");
        } else if (count > maxCount) {
            throw new FormatDataException("Count " + count + " exceeds the limit of " + maxCount + " for data of unknown length at offset " + position);
        }

        return (int) Math.min(count, Integer.MAX_VALUE);
    }

    public int checkCount(long count, int minElementSize) throws FormatDataException {
        return checkCount(count, minElementSize, Integer.MAX_VALUE);
    }

    public boolean readBool() throws IOException {
        return next() != 0;
    }

    public int readU8() throws IOException {
        return next();
    }

    public byte readI8() throws IOException {
        return (byte) next();
    }

    public int readU16LE() throws IOException {
        byte[] b = fixed(2);
        return (b[0] & 0xFF) | (b[1] & 0xFF) << 8;
    }

    public int readU16BE() throws IOException {
        byte[] b = fixed(2);
        return (b[0] & 0xFF) << 8 | (b[1] & 0xFF);
    }

    public short readI16LE() throws IOException {
        return (short) readU16LE();
    }

    public short readI16BE() throws IOException {
        return (short) readU16BE();
    }

    public int readI32LE() throws IOException {
        byte[] b = fixed(4);
        return (b[0] & 0xFF) | (b[1] & 0xFF) << 8 | (b[2] & 0xFF) << 16 | (b[3] & 0xFF) << 24;
    }

    public int readI32BE() throws IOException {
        byte[] b = fixed(4);
        return (b[0] & 0xFF) << 24 | (b[1] & 0xFF) << 16 | (b[2] & 0xFF) << 8 | (b[3] & 0xFF);
    }

    public long readU32LE() throws IOException {
        return readI32LE() & 0xFFFFFFFFL;
    }

    public long readU32BE() throws IOException {
        return readI32BE() & 0xFFFFFFFFL;
    }

    public long readI64LE() throws IOException {
        byte[] b = fixed(8);
        long value = 0;
        for (int i = 7; i >= 0; i--) value = value << 8 | (b[i] & 0xFF);
        return value;
    }

    public long readI64BE() throws IOException {
        byte[] b = fixed(8);
        long value = 0;
        for (int i = 0; i < 8; i++) value = value << 8 | (b[i] & 0xFF);
        return value;
    }

    /** The bits of an unsigned 64-bit value. */
    public long readU64LE() throws IOException {
        return readI64LE();
    }

    public long readU64BE() throws IOException {
        return readI64BE();
    }

    public float readF16LE() throws IOException {
        return halfToFloat(readU16LE());
    }

    public float readF16BE() throws IOException {
        return halfToFloat(readU16BE());
    }

    /** The value of IEEE 754 half precision bits. */
    static float halfToFloat(int bits) {
        int sign = (bits & 0x8000) << 16;
        int exponent = (bits >>> 10) & 0x1F;
        int mantissa = bits & 0x3FF;
        if (exponent == 0x1F) return Float.intBitsToFloat(sign | 0x7F800000 | mantissa << 13);
        if (exponent == 0) {
            float value = mantissa * 0x1p-24f;
            return sign == 0 ? value : -value;
        }

        return Float.intBitsToFloat(sign | (exponent + 112) << 23 | mantissa << 13);
    }

    public float readF32LE() throws IOException {
        return Float.intBitsToFloat(readI32LE());
    }

    public float readF32BE() throws IOException {
        return Float.intBitsToFloat(readI32BE());
    }

    public double readF64LE() throws IOException {
        return Double.longBitsToDouble(readI64LE());
    }

    public double readF64BE() throws IOException {
        return Double.longBitsToDouble(readI64BE());
    }

    public long readVarUInt32() throws IOException {
        long result = 0;
        for (int shift = 0; shift < 35; shift += 7) {
            int b = next();
            result |= (long) (b & 0x7F) << shift;
            if ((b & 0x80) == 0) {
                if (shift == 28 && b > 0x0F) throw new FormatDataException("VarUInt32 overflow at offset " + (position - 1));
                return result;
            }
        }

        throw new FormatDataException("VarUInt32 longer than 5 bytes at offset " + position);
    }

    /** The bits of an unsigned 64-bit varint. */
    public long readVarUInt64() throws IOException {
        long result = 0;
        for (int shift = 0; shift < 70; shift += 7) {
            int b = next();
            result |= (long) (b & 0x7F) << shift;
            if ((b & 0x80) == 0) {
                if (shift == 63 && b > 0x01) throw new FormatDataException("VarUInt64 overflow at offset " + (position - 1));
                return result;
            }
        }

        throw new FormatDataException("VarUInt64 longer than 10 bytes at offset " + position);
    }

    /** Two's complement LEB128 (Java VarInt). */
    public int readVarInt32() throws IOException {
        return (int) readVarUInt32();
    }

    public long readVarInt64() throws IOException {
        return readVarUInt64();
    }

    /** Zigzag LEB128 (e.g. the Bedrock "varint"). */
    public int readZigZag32() throws IOException {
        int value = (int) readVarUInt32();
        return (value >>> 1) ^ -(value & 1);
    }

    public long readZigZag64() throws IOException {
        long value = readVarUInt64();
        return (value >>> 1) ^ -(value & 1);
    }

    /** A UUID as two little-endian 64-bit halves, most significant half first. */
    public UUID readUuidLE() throws IOException {
        long most = readI64LE();
        return new UUID(most, readI64LE());
    }

    /** A UUID in RFC 4122 byte order (two big-endian 64-bit halves). */
    public UUID readUuidBE() throws IOException {
        long most = readI64BE();
        return new UUID(most, readI64BE());
    }

    // UTF-8 shorthands.
    public String readUtf8(int byteCount) throws IOException {
        return readString(byteCount, FormatEncoding.UTF8, false);
    }

    public String readUtf8(int byteCount, boolean strict) throws IOException {
        return readString(byteCount, FormatEncoding.UTF8, strict);
    }

    public String readUtf8Padded(int byteCount, int pad) throws IOException {
        return readStringPadded(byteCount, pad, FormatEncoding.UTF8, false);
    }

    public String readUtf8Padded(int byteCount, int pad, boolean strict) throws IOException {
        return readStringPadded(byteCount, pad, FormatEncoding.UTF8, strict);
    }

    public String readUtf8Terminated(int byteCount) throws IOException {
        return readStringTerminated(byteCount, FormatEncoding.UTF8, false, false);
    }

    public String readUtf8Terminated(int byteCount, boolean strict, boolean checkPadding) throws IOException {
        return readStringTerminated(byteCount, FormatEncoding.UTF8, strict, checkPadding);
    }

    public String readUtf8Zero() throws IOException {
        return readStringZero(FormatEncoding.UTF8, false);
    }

    public String readUtf8Zero(boolean strict) throws IOException {
        return readStringZero(FormatEncoding.UTF8, strict);
    }

    public String readUtf8ToEnd() throws IOException {
        return readStringToEnd(FormatEncoding.UTF8, false);
    }

    public String readUtf8ToEnd(boolean strict) throws IOException {
        return readStringToEnd(FormatEncoding.UTF8, strict);
    }

    /** Text; {@code strict} rejects invalid bytes instead of replacing them with U+FFFD. */
    public String readString(int byteCount, FormatEncoding encoding, boolean strict) throws IOException {
        long offset = position;
        byte[] bytes = take(byteCount);
        return decode(bytes, bytes.length, encoding, strict, offset);
    }

    /** A string in a field of {@code byteCount} bytes, without the trailing {@code pad} bytes. */
    public String readStringPadded(int byteCount, int pad, FormatEncoding encoding, boolean strict) throws IOException {
        long offset = position;
        byte[] bytes = take(byteCount);
        int end = bytes.length;
        while (end > 0 && bytes[end - 1] == (byte) pad) end--;
        return decode(bytes, end, encoding, strict, offset);
    }

    /**
     * A string in a field of {@code byteCount} bytes that ends at the first zero byte, or with the field.
     * {@code checkPadding} rejects non-zero bytes after the terminator.
     */
    public String readStringTerminated(int byteCount, FormatEncoding encoding, boolean strict, boolean checkPadding) throws IOException {
        long offset = position;
        byte[] bytes = take(byteCount);
        int end = 0;
        while (end < bytes.length && bytes[end] != 0) end++;
        if (checkPadding) {
            for (int i = end; i < bytes.length; i++) {
                if (bytes[i] != 0) {
                    throw new FormatDataException(String.format("Padding byte 0x%02x at offset %d after the string terminator", bytes[i] & 0xFF, offset + i));
                }
            }
        }

        return decode(bytes, end, encoding, strict, offset);
    }

    public String readStringZero(FormatEncoding encoding, boolean strict) throws IOException {
        long offset = position;
        ByteArrayOutputStream bytes = new ByteArrayOutputStream();
        while (true) {
            if (length >= 0 && position >= length) throw new FormatDataException("Missing string terminator after offset " + position);
            int b = next();
            if (b == 0) break;
            bytes.write(b);
        }

        byte[] text = bytes.toByteArray();
        return decode(text, text.length, encoding, strict, offset);
    }

    /** The rest of the data as text. */
    public String readStringToEnd(FormatEncoding encoding, boolean strict) throws IOException {
        long offset = position;
        byte[] bytes = readToEnd();
        return decode(bytes, bytes.length, encoding, strict, offset);
    }

    /** The first {@code count} bytes as text; {@code strict} rejects invalid bytes instead of replacing them. */
    private static String decode(byte[] bytes, int count, FormatEncoding encoding, boolean strict, long offset) throws FormatDataException {
        if (!strict) return new String(bytes, 0, count, encoding.charset);
        try {
            return encoding.charset.newDecoder()
                .onMalformedInput(CodingErrorAction.REPORT)
                .onUnmappableCharacter(CodingErrorAction.REPORT)
                .decode(ByteBuffer.wrap(bytes, 0, count))
                .toString();
        } catch (CharacterCodingException e) {
            throw new FormatDataException("Invalid " + encoding.label + " in the string at offset " + offset);
        }
    }

    /** Skips the rest of the data, the fill of a sized region; {@code check} rejects bytes that don't repeat {@code pattern}. */
    public void skipFill(byte[] pattern, boolean check) throws IOException {
        long offset = position;
        byte[] fill = readToEnd();
        if (!check) return;
        for (int i = 0; i < fill.length; i++) {
            if (fill[i] != pattern[i % pattern.length]) {
                throw new FormatDataException(String.format("Byte 0x%02x at offset %d of the region is not its fill", fill[i] & 0xFF, offset + i));
            }
        }
    }

    public byte[] readBytes(int count) throws IOException {
        return take(count);
    }

    /** The rest of the data. */
    public byte[] readToEnd() throws IOException {
        if (length >= 0) return take((int) Math.min(remaining(), Integer.MAX_VALUE));
        ByteArrayOutputStream bytes = new ByteArrayOutputStream();
        if (peeked >= 0) {
            bytes.write(peeked);
            peeked = -1;
        }

        byte[] buffer = new byte[8192];
        int read;
        while ((read = input.read(buffer)) > 0) bytes.write(buffer, 0, read);
        position += bytes.size();
        if (recording != null) recording.write(bytes.toByteArray());
        return bytes.toByteArray();
    }

    /** Starts recording the bytes read from here on; {@link #stopRecording()} returns them. */
    public void startRecording() {
        recording = new ByteArrayOutputStream();
    }

    /** Stops recording and returns the bytes read since {@link #startRecording()} (none when not recording). */
    public byte[] stopRecording() {
        byte[] bytes = recording != null ? recording.toByteArray() : new byte[0];
        recording = null;
        return bytes;
    }

    /** Skips {@code count} bytes. */
    public void skip(int count) throws IOException {
        byte[] buffer = new byte[Math.min(count, 8192)];
        while (count > 0) {
            int chunk = Math.min(count, buffer.length);
            fill(buffer, chunk);
            count -= chunk;
        }
    }
}
